style.ha-markdown$:
{% set indicator_state = states('sensor.prusaxl') %}
ha-icon {
  color: {{ '#FFC107' if indicator_state == 'paused' else '#FF9800' if indicator_state in ['attention', 'error'] else '#FE6E31' }};
  --mdc-icon-size: 24px;
  display: inline-block;
  margin-right: 6px;
  vertical-align: middle;
  animation: {{ 'printer-soft-pulse 3s ease-in-out infinite' if indicator_state == 'printing' else 'none' }};
}
@keyframes printer-soft-pulse {
  0%, 100% { opacity: 1; filter: drop-shadow(0 0 3px rgba(254,110,49,0.45)); }
  50% { opacity: 0.5; filter: drop-shadow(0 0 0px rgba(254,110,49,0)); }
}
@media (prefers-reduced-motion: reduce) {
  ha-icon { animation: none; }
}

