{% set state = states('sensor.prusaxl') %}
{% set value = states('sensor.prusaxl_status') %}
{% set valid = is_number(value) and 0 <= value | float(0) <= 100 %}
{% set progress = value | float(0) if valid else 0 %}
{% set color = '#FFC107' if state == 'paused' else '#FF9800' if state in ['attention', 'error'] else '#FE6E31' %}
ha-card { position: relative; overflow: hidden; }
ha-card::before, ha-card::after {
 content: '';
 position: absolute;
 bottom: 0;
 left: 0;
 height: 4px;
 pointer-events: none;
 opacity: {{ 1 if valid else 0 }};
}
ha-card::before { width: 100%; background: rgba(254,110,49,.15); }
ha-card::after {
 width: {{ progress }}%;
 background-color: {{ color }};
 background-image: linear-gradient(110deg, transparent 30%, rgba(255,255,255,.35) 50%, transparent 70%);
 background-size: 90px 100%;
 transition: width 1s ease, background-color .5s ease;
 animation: {{ 'prusa-progress-flow 3s linear infinite' if state == 'printing' and valid and progress < 100 else 'none' }};
}
@keyframes prusa-progress-flow { from { background-position: 0 0; } to { background-position: 90px 0; } }
@media(prefers-reduced-motion:reduce) { ha-card::after { animation:none; transition:none; } }
